import json
from pathlib import Path
base=Path('/tmp/objective-recovery-runs/u284/packet')
for path in [base/'abba-oversubscription/screen.json',base/'abba-oversubscription/qualify.json',base/'c54-trace/timing-trace.json']:
 d=json.load(open(path)); print('\n',path.name,d.keys())
 if 'looks' in d:
  print('status',d.get('status'),'phase',d.get('phase'),'looks',len(d['looks']))
