   print(l.get('route'),l.get('status'), l.get('resident_service_seconds'),l.get('complete_lifecycle_seconds'),l.get('busy_cores'),l.get('resident_service_union_seconds'), l.keys())
 else:
  print('keys',d.keys()); print('trace events',len(d.get('events',[])),'jobs',len(d.get('jobs',[])))
